from html.parser import HTMLParser


class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.lang, self.ids, self.fors, self.inputs, self.imgs = None, set(), set(), [], []
        self.label_depth, self.wrapped, self.button, self.button_text = 0, set(), 0, ''
        self.button_named = False

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if a.get('id'):
            self.ids.add(a['id'])
        if tag == 'html':
            self.lang = a.get('lang')
        elif tag == 'label':
            self.label_depth += 1
            if a.get('for'):
                self.fors.add(a['for'])
        elif tag == 'input' and a.get('type') not in ('hidden', 'submit'):
            self.inputs.append(a)
            if self.label_depth:
                self.wrapped.add(a.get('name'))
        elif tag == 'img':
            self.imgs.append(a)
            if self.button and (a.get('alt') or '').strip():
                self.button_named = True
        elif tag == 'button':
            self.button += 1
            if (a.get('aria-label') or '').strip():
                self.button_named = True

    def handle_endtag(self, tag):
        if tag == 'label':
            self.label_depth -= 1
        elif tag == 'button':
            self.button -= 1

    def handle_data(self, data):
        if self.button and data.strip():
            self.button_named = True


p = P()
p.feed(open('static/signup.html').read())
assert p.lang, 'the html element has no lang'
names = {i.get('name') for i in p.inputs}
assert {'email', 'name', 'newsletter'} <= names, f'fields missing: {names}'
for i in p.inputs:
    tied = (i.get('id') in p.fors) or (i.get('name') in p.wrapped) or (i.get('aria-labelledby') or '') in p.ids
    assert tied, f"input {i.get('name')} has no label tied to it (a placeholder is not a label)"
for img in p.imgs:
    assert img.get('alt') is not None, f"img {img.get('src')} has no alt"
logo = [i for i in p.imgs if i.get('src') == 'logo.png']
assert logo and logo[0]['alt'].strip(), 'the logo needs a text alternative'
assert p.button_named, 'the submit button has no accessible name'

